//! Fixed-colour paint layers for the multi-colour catalog assets, drawn over
//! the base silhouette in `catalog_shapes`. Generated by processing the
//! vendored catalog SVGs with `super::process_upload`, one recoloured isolate
//! per accent colour (the official board draws explicit fills as-is and
//! everything unfilled in the snake's colour). A near-white composite layer
//! (#ffffff) is emitted only for assets that keep at least one accent layer,
//! so single-colour art — whose white details are cut-outs in the base path —
//! never appears here. A static table, so nothing is processed at runtime.
//! To regenerate:
//!
//! ```text
//! cargo test -p arena --test design_kit_catalog -- --ignored write_catalog_layers
//! ```

use super::{AssetKind, FillRule};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CatalogLayer {
    /// Fixed paint, lowercase `#rrggbb` (the white composite is `#ffffff`).
    pub fill: &'static str,
    /// Absolute `M`/`L`/`Q`/`C`/`Z` commands in the 100x100 box, like `CatalogShape::d`.
    pub d: &'static str,
    pub fill_rule: FillRule,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CatalogLayerArt {
    pub kind: AssetKind,
    /// The media file's name without `.svg`, like `CatalogShape::file`.
    pub file: &'static str,
    /// Occlusion-resolved (mutually disjoint): accents in first-appearance
    /// order, then the white composite.
    pub layers: &'static [CatalogLayer],
}

