/// A multi-colour asset's layers by kind and media file; single-colour art: empty.
pub fn find(kind: AssetKind, file: &str) -> &'static [CatalogLayer] {
    CATALOG_LAYER_ART
        .iter()
        .find(|a| a.kind == kind && a.file == file)
        .map_or(&[], |a| a.layers)
}
